input.new_string:
const { trim, slugify } = require('../src/str');

test('trim', () => {
  assert.strictEqual(trim('  a  '), 'a');
});

test('slugify lowercases', () => {
  assert.strictEqual(slugify('Hello'), 'hello');
});

test('slugify trims surrounding whitespace', () => {
  assert.strictEqual(slugify('  hello  '), 'hello');
});

test('slugify replaces a run of non-alphanumerics with a single dash', () => {
  assert.strictEqual(slugify('hello world'), 'hello-world');
  assert.strictEqual(slugify('hello   world'), 'hello-world');
  assert.strictEqual(slugify('hello_world'), 'hello-world');
  assert.strictEqual(slugify('hello -- world'), 'hello-world');
});

test('slugify strips leading and trailing dashes', () => {
  assert.strictEqual(slugify('---hello---'), 'hello');
  assert.strictEqual(slugify('!!!hello!!!'), 'hello');
});

test('slugify keeps digits', () => {
  assert.strictEqual(slugify('Top 10 Books'), 'top-10-books');
});

test('slugify handles a full sentence', () => {
  assert.strictEqual(slugify('  The Quick, Brown Fox! '), 'the-quick-brown-fox');
});

test('slugify returns empty string when nothing survives', () => {
  assert.strictEqual(slugify(''), '');
  assert.strictEqual(slugify('   '), '');
  assert.strictEqual(slugify('!!!'), '');
});

